import sys
from array import array

def main():
    input = sys.stdin.buffer.readline
    n, q = map(int, input().split())
    parent = array('i', range(n))
    sz = array('i', [1]) * n
    left = array('i', range(n))
    right = array('i', range(n))
    color = array('i', range(1, n + 1))
    cnt = array('i', [0]) * (n + 1)
    cnt[1:] = array('i', [1]) * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return a
        if sz[a] < sz[b]:
            a, b = b, a
        parent[b] = a
        sz[a] += sz[b]
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    out = []
    for _ in range(q):
        parts = list(map(int, input().split()))
        if parts[0] == 1:
            _, x, c = parts
            r = find(x - 1)
            old = color[r]
            if old != c:
                cnt[old] -= sz[r]
                cnt[c] += sz[r]
                color[r] = c
            if left[r] > 0:
                lroot = find(left[r] - 1)
                if color[lroot] == color[r]:
                    r = merge(r, lroot)
            if right[r] + 1 < n:
                rroot = find(right[r] + 1)
                if color[rroot] == color[r]:
                    r = merge(r, rroot)
        else:
            out.append(str(cnt[parts[1]]))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

