from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Each pair (a, b), with a < b, becomes active when the right
        # endpoint reaches b. For a given right endpoint r, valid starts
        # must be greater than every active a, so the largest active a
        # determines the number of valid subarrays ending at r.
        buckets = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            buckets[b].append((a, idx))

        first_value = first_id = second_value = 0
        gains = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if a > first_value:
                    second_value = first_value
                    first_value, first_id = a, idx
                elif a > second_value:
                    # Equal maximum values are retained as the runner-up,
                    # so removing just one of them produces no gain.
                    second_value = a

            total += r - first_value
            if first_value:
                gains[first_id] += first_value - second_value

        return total + max(gains)

