    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Pascal's triangle: C[a][b] counts choices of b set bits in a places.
        C = [[0] * (n + 1) for _ in range(n + 1)]
        C[0][0] = 1
        for a in range(1, n + 1):
            C[a][0] = C[a][a] = 1
            for b in range(1, a):
                C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD

        # A number with j set bits takes 1 + steps(j) operations to reach 1.
        good = [False] * (n + 1)
        for j in range(1, n + 1):
            value = j
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[j] = steps + 1 <= k

        ans = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                # Make this bit 0, then freely choose the remaining suffix.
                remaining = n - i - 1
                for ones in range(1, n + 1):
                    if good[ones]:
                        need = ones - prefix_ones
                        if 0 <= need <= remaining:
                            ans += C[remaining][need]
                prefix_ones += 1
        return ans % MOD

